def signal(obs):
    out = {}
    # --- COIN momentum (50 and 100 step) ---
    try:
        c = obs.hist('COIN', 'mid', 120)
        # past returns
        if c.size >= 51 and not np.isnan(c[-1]) and not np.isnan(c[-51]):
            past50 = c[-1] - c[-51]
        else:
            past50 = 0
        if c.size >= 101 and not np.isnan(c[-1]) and not np.isnan(c[-101]):
            past100 = c[-1] - c[-101]
        else:
            past100 = 0
        # normalize by typical vol (approx std of past returns)
        # 13.7 for 50, 23.6 for 100
        s50 = past50 / 14.0
        s100 = past100 / 24.0
        sig = 0.6 * s50 + 0.4 * s100
        # dead zone to avoid spread bleed
        if abs(sig) < 0.30:
            sig = 0
        else:
            sig = sig * 0.65
            if sig > 1: sig = 1
            if sig < -1: sig = -1
        out['COIN'] = float(sig)
    except:
        pass

    # --- COIN.P premium fade ---
    try:
        # use last mids
        cc = obs.last('COIN', 'mid')
        pp = obs.last('COIN.P', 'mid')
        if not np.isnan(cc) and not np.isnan(pp):
            prem = pp - cc
            # long-run mean ~7, std ~13
            z = (prem - 7.0) / 13.0
            tp = -z * 0.35
            if abs(tp) < 0.20:
                tp = 0
            else:
                if tp > 1: tp = 1
                if tp < -1: tp = -1
            out['COIN.P'] = float(tp)
        else:
            out['COIN.P'] = 0
    except:
        pass

    # --- Imbalance signals for A, C, MEME ---
    # A has strongest imbalance IC ~0.34-0.46, COIN also but COIN already used
    for asset in ['A', 'C', 'MEME']:
        try:
            imb = obs.last(asset, 'imbalance')
            if np.isnan(imb):
                continue
            t = imb * 1.6
            if abs(t) < 0.18:
                t = 0
            if t > 1: t = 1
            if t < -1: t = -1
            out[asset] = float(t)
        except:
            continue
    # keep B and IDX flat to avoid costly basket arb
    out['B'] = 0
    out['IDX'] = 0
    return out

